#include "util/FileIO.h"

namespace
{
namespace fs = std::filesystem;
using nlohmann::json;

constexpr double kSampleRate = 48000.0;
constexpr int kBlock = 256;
/// What every preset is brought to, as the mean of its loudness on the three clips.
constexpr double kTargetLufs = -20.0;
constexpr double kMeanToleranceLu = 1.0;
/// One clip against the target. Wider, because a clean amp follows how hard each clip is
/// played and a saturated one does not, and no single trim can make both agree on all three.
constexpr double kClipToleranceLu = 3.5;
constexpr double kPeakCeilingDbfs = -0.5;
constexpr const char* kArchiveName = "Sepia-Factory.soundshed.presets";
constexpr const char* kClips[] = {"clean-chords", "palm-mute", "lead"};

int gFailures = 0;
int gChecks = 0;

void Check(bool condition, const std::string& what, const std::string& detail = "")
{
    ++gChecks;
    gFailures += condition ? 0 : 1;

    // Sixty presets times a dozen checks: only the failures are worth a line each.
    if (!condition)
    {
        std::cout << "  [FAIL] " << what << (detail.empty() ? "" : "  (" + detail + ")") << std::endl;
    }
}

std::string Num(double v, int precision = 2)
{
    char buffer[64];
    std::snprintf(buffer, sizeof(buffer), "%.*f", precision, v);
    return buffer;
}

fs::path ArchivePath()
{
    return fs::path(GUITARFX_DEMO_AUDIO_DIR) / ".." / "presets" / "factory" / kArchiveName;
}

fs::path ClipPath(const std::string& name)
{
    return fs::path(GUITARFX_DEMO_AUDIO_DIR) / ".." / ".." / "tests" / "testdata" / "di" / (name + ".wav");
}

std::string Lower(std::string text)
{
    std::transform(text.begin(), text.end(), text.begin(), [](unsigned char c) { return std::tolower(c); });
    return text;
}

struct Pack
{
    json document;
    std::vector<guitarfx::Preset> presets;
    std::map<std::string, std::string> groupOf; // preset id -> folder name
};

std::optional<Pack> LoadPack()
{
    const auto bytes = guitarfx::util::ReadFileBytes(ArchivePath());
    Check(!bytes.empty(), "the archive is bundled", ArchivePath().string());

    if (bytes.empty())
    {
        return std::nullopt;
    }

    const auto manifest = guitarfx::controller_detail::ExtractZipEntry(bytes, "presets.json");
    Check(manifest.has_value(), "the archive holds presets.json");

    if (!manifest)
    {
        return std::nullopt;
    }

    Pack pack;
    pack.document = json::parse(manifest->begin(), manifest->end(), nullptr, false);
    Check(pack.document.is_object() && pack.document.value("presets", json::array()).is_array(),
          "presets.json parses");

    if (!pack.document.is_object())
    {
        return std::nullopt;
    }

    for (const auto& entry : pack.document["presets"])
    {
        auto preset = guitarfx::PresetStorage::DeserializeFromJson(entry.dump());
        Check(preset.has_value(), entry.value("name", std::string("?")) + " deserialises");

        if (preset)
        {
            pack.presets.push_back(std::move(*preset));
        }
    }

    for (const auto& top : pack.document.value("presetFolders", json::array()))
    {
        for (const auto& folder : top.value("children", json::array()))
        {
            for (const auto& id : folder.value("presetIds", json::array()))
            {
                pack.groupOf[id.get<std::string>()] = folder.value("name", std::string{});
            }
        }
    }

    return pack;
}

bool IsHighGainGroup(const std::string& group)
{
    return group == "Metal";
}

void TestSelfContained(const Pack& pack)
{
    std::cout << "\nSelf-contained and well-formed" << std::endl;
    auto& registry = guitarfx::EffectRegistry::Instance();

    Check(pack.document.value("resources", json::array()).empty(), "the archive lists no resources");
    Check(pack.presets.size() >= 60, "at least sixty presets", std::to_string(pack.presets.size()));

    const std::map<std::string, std::size_t> expected = {{"Clean & Indie", 12}, {"Lo-Fi", 8},
                                                         {"Shoegaze & Ambient", 8}, {"Blues & Classic Rock", 10},
                                                         {"Grunge & Punk", 10},  {"Metal", 12}};
    std::map<std::string, std::size_t> counts;

    for (const auto& [id, group] : pack.groupOf)
    {
        ++counts[group];
    }

    for (const auto& [group, count] : expected)
    {
        Check(counts[group] >= count, group + " has its " + std::to_string(count) + " presets",
              std::to_string(counts[group]));
    }

    // Names an original pack has no business using. Lower case; matched as substrings.
    const std::vector<std::string> denied = {"soundshed", "roomtone", "black album", "karnivore", "dumble",
                                             "marshall", "fender",   "mesa",        "boss ",     "ibanez",
                                             "demarco",  "nirvana",  "metallica",   "hendrix",   "tame impala"};
    std::set<std::string> names;
    std::set<std::string> ids;

    for (const auto& preset : pack.presets)
    {
        Check(names.insert(Lower(preset.name)).second && ids.insert(preset.id).second,
              preset.name + " has a name and id of its own");
        Check(pack.groupOf.contains(preset.id), preset.name + " is filed in a group");
        Check(preset.embeddedResources.empty(), preset.name + " embeds no resource");

        for (const auto& word : denied)
        {
            Check(Lower(preset.name).find(word) == std::string::npos, preset.name + " borrows no name", word);
        }

        Check(preset.scenes.size() == 1, preset.name + " has one scene");
        bool gateFirst = false;
        std::string first;

        for (const auto& edge : preset.graph.edges)
        {
            if (edge.from == "__input__")
            {
                first = edge.to;
            }
        }

        for (const auto& node : preset.graph.nodes)
        {
            if (node.type == guitarfx::kNodeTypeInput || node.type == guitarfx::kNodeTypeOutput)
            {
                continue;
            }

            const auto info = registry.GetTypeInfo(registry.Resolve(node.type));
            Check(info.has_value(), preset.name + ": " + node.label + " is a registered effect", node.type);
            Check(node.resources.empty(), preset.name + ": " + node.label + " references no file");

            if (!info)
            {
                continue;
            }

            Check(!info->requiresResource, preset.name + ": " + node.label + " needs no model or IR");
            gateFirst = gateFirst || (node.id == first && registry.Resolve("dynamics_gate") == info->type);

            for (const auto& [key, value] : node.params)
            {
                const auto* param = registry.FindParameter(info->type, key);
                Check(param != nullptr, preset.name + ": " + node.label + " has a parameter " + key);
                Check(param == nullptr || (value >= param->minValue && value <= param->maxValue),
                      preset.name + ": " + node.label + "." + key + " is within range", Num(value));
            }

            for (const auto& param : info->parameters)
            {
                Check(node.params.contains(param.id),
                      preset.name + ": " + node.label + " writes out " + param.id + " rather than rely on a default");
            }
        }

        const auto group = pack.groupOf.contains(preset.id) ? pack.groupOf.at(preset.id) : std::string{};

        if (IsHighGainGroup(group) && Lower(preset.name).find("clean") == std::string::npos)
        {
            Check(gateFirst, preset.name + " opens with a noise gate");
        }
    }
}

/// A controller on a profile of its own, with the pack bundled where the app keeps it.
class Rig
{
  public:
    Rig()
        : mProfile(fs::temp_directory_path() / ("sepia-pack-test-" + std::to_string(std::rand())))
    {
        std::error_code ec;
        fs::remove_all(mProfile, ec);
        const auto factory = mProfile / "bundled" / "ui" / "presets" / "factory";
        fs::create_directories(factory, ec);
        fs::copy_file(ArchivePath(), factory / kArchiveName, fs::copy_options::overwrite_existing, ec);
        audio_snapshot::SetSettingsEnvRoot(mProfile);
        mHost = std::make_unique<audio_snapshot::SnapshotHost>(mProfile, kSampleRate, kBlock);
        mController = std::make_unique<guitarfx::PluginController>(*mHost);
        mController->Initialize();
        mController->Prepare(kSampleRate, kBlock);
        mController->OnIdle();
    }

    ~Rig()
    {
        mController.reset();
        mHost.reset();
        std::error_code ec;
        fs::remove_all(mProfile, ec);
    }

    [[nodiscard]] std::string LoadById(const std::string& id)
    {
        mController->HandleUIMessage(json{{"type", "loadPreset"}, {"presetId", id}}.dump());
        mController->OnIdle();
        const auto& active = mController->GetActivePreset();
        return active ? active->id : std::string{};
    }

    void Load(const guitarfx::Preset& preset)
    {
        mController->HandleUIMessage(
            json{{"type", "loadPreset"},
                 {"presetId", preset.id},
                 {"preset", json::parse(guitarfx::PresetStorage::SerializeToJson(preset))}}
                .dump());
        mController->OnIdle();
    }

    audio_snapshot::Render Play(const std::vector<float>& input)
    {
        return audio_snapshot::RenderBlocks(
            input, kBlock, [&](float** in, float** out, int n) { return mController->ProcessAudio(in, out, n); });
    }

    /// Silence, with the idle work an editor's timer would do: lets a load's fade finish and
    /// the previous preset's tail die away.
    audio_snapshot::Render Settle(double seconds)
    {
        audio_snapshot::Render last;
        const std::vector<float> tenth(static_cast<std::size_t>(kSampleRate * 0.1), 0.0f);

        for (int i = 0; i < static_cast<int>(seconds * 10.0); ++i)
        {
            last = Play(tenth);
            mController->OnIdle();
        }

        return last;
    }

  private:
    fs::path mProfile;
    std::unique_ptr<audio_snapshot::SnapshotHost> mHost;
    std::unique_ptr<guitarfx::PluginController> mController;
};

std::vector<float> LoadClip(const std::string& name)
{
    double rate = 0.0;
    const auto samples = audio_snapshot::ReadAudioMono(ClipPath(name), rate);
    Check(!samples.empty() && rate == kSampleRate, name + ".wav is there, at 48 kHz", ClipPath(name).string());
    return std::vector<float>(samples.begin(), samples.end());
}

struct Level
{
    std::optional<double> lufs;
    double peakDbfs = -200.0;
    double rmsDbfs = -200.0;
    double largestStep = 0.0;
    bool finite = true;
};

Level Measure(const audio_snapshot::Render& render)
{
    Level level;
    guitarfx::loudness::IntegratedLoudnessMeter meter(kSampleRate);
    meter.Push(render.left.data(), render.right.data(), render.left.size());
    const auto result = meter.Result();
    level.lufs = result.integratedLufs;
    level.peakDbfs = result.peakDbfs.value_or(-200.0);
    level.rmsDbfs = result.rmsDbfs.value_or(-200.0);

    for (std::size_t n = 0; n < render.left.size(); ++n)
    {
        level.finite = level.finite && !audio_snapshot::IsNonFinite(render.left[n]) &&
                       !audio_snapshot::IsNonFinite(render.right[n]);

        if (n > 0)
        {
            level.largestStep =
                std::max(level.largestStep, static_cast<double>(std::fabs(render.left[n] - render.left[n - 1])));
        }
    }

    return level;
}

std::vector<float> Scaled(const std::vector<float>& input, double db)
{
    const auto gain = static_cast<float>(std::pow(10.0, db / 20.0));
    std::vector<float> out(input.size());
    std::transform(input.begin(), input.end(), out.begin(), [gain](float v) { return v * gain; });
    return out;
}

void TestOfferedById(const Pack& pack)
{
    std::cout << "\nOffered by the app" << std::endl;
    Rig rig;
    int found = 0;

    for (const auto& preset : pack.presets)
    {
        found += rig.LoadById(preset.id).empty() ? 0 : 1;
    }

    Check(found == static_cast<int>(pack.presets.size()), "a fresh install loads every pack preset by its id",
          std::to_string(found) + " of " + std::to_string(pack.presets.size()));
}

json TestLevels(const Pack& pack, bool measureOnly)
{
    std::cout << "\nLevels" << (measureOnly ? " (measuring only)" : "") << std::endl;
    std::map<std::string, std::vector<float>> clips;

    for (const char* name : kClips)
    {
        clips[name] = LoadClip(name);
    }

    json measured = json::array();
    Rig rig;
    std::printf("  %-26s %7s %7s %7s %7s %6s %6s\n", "preset", "chords", "mute", "lead", "mean", "peak", "comp");

    for (const auto& preset : pack.presets)
    {
        const auto group = pack.groupOf.contains(preset.id) ? pack.groupOf.at(preset.id) : std::string{};
        rig.Load(preset);
        const auto idle = Measure(rig.Settle(1.0));
        json entry = {{"name", preset.name}, {"group", group}, {"clips", json::array()}};
        double sum = 0.0;
        double peak = -200.0;
        int counted = 0;
        std::vector<double> perClip;

        for (const char* name : kClips)
        {
            const auto level = Measure(rig.Play(clips[name]));
            rig.Settle(1.5);
            entry["clips"].push_back(
                {{"clip", name}, {"lufs", level.lufs ? json(*level.lufs) : json(nullptr)}, {"peakDbfs", level.peakDbfs}});
            Check(level.finite, preset.name + " stays finite on " + name);
            perClip.push_back(level.lufs.value_or(-200.0));
            peak = std::max(peak, level.peakDbfs);

            if (level.lufs)
            {
                sum += *level.lufs;
                ++counted;
            }
        }

        // How much of a 12 dB drop in playing comes out the other end: 12 is linear, 0 is a wall.
        const double loud = Measure(rig.Play(clips["palm-mute"])).rmsDbfs;
        rig.Settle(1.5);
        const double quiet = Measure(rig.Play(Scaled(clips["palm-mute"], -12.0))).rmsDbfs;
        rig.Settle(1.0);
        const double followed = loud - quiet;
        const double mean = counted > 0 ? sum / counted : -200.0;
        entry["meanLufs"] = mean;
        entry["peakDbfs"] = peak;
        entry["followedDb"] = followed;
        measured.push_back(entry);
        std::printf("  %-26s %7.1f %7.1f %7.1f %7.1f %6.1f %6.1f\n", preset.name.c_str(), perClip[0], perClip[1],
                    perClip[2], mean, peak, followed);

        Check(counted == 3, preset.name + " makes sound on all three clips");

        if (measureOnly)
        {
            continue;
        }

        Check(std::fabs(mean - kTargetLufs) <= kMeanToleranceLu, preset.name + " is at the pack's loudness",
              Num(mean) + " LUFS, target " + Num(kTargetLufs));

        for (std::size_t i = 0; i < perClip.size(); ++i)
        {
            Check(std::fabs(perClip[i] - kTargetLufs) <= kClipToleranceLu,
                  preset.name + " is near it on " + kClips[i], Num(perClip[i]) + " LUFS");
        }

        Check(peak <= kPeakCeilingDbfs, preset.name + " never reaches full scale", Num(peak) + " dBFS");

        const bool clean = Lower(preset.name).find("clean") != std::string::npos;

        if (IsHighGainGroup(group) && !clean)
        {
            Check(followed < 6.0, preset.name + " is high gain: it flattens a 12 dB drop to under 6",
                  Num(followed) + " dB");
            Check(idle.rmsDbfs < -70.0, preset.name + " is quiet with nothing played", Num(idle.rmsDbfs) + " dBFS");
        }

        if (group == "Clean & Indie" && Lower(preset.name).find("lead") == std::string::npos &&
            Lower(preset.name).find("edge") == std::string::npos)
        {
            Check(followed > 5.0, preset.name + " is clean: most of a 12 dB drop comes through",
                  Num(followed) + " dB");
        }
    }

    return measured;
}

void TestSwitchingDoesNotClick(const Pack& pack)
{
    std::cout << "\nSwitching presets" << std::endl;
    const auto clip = LoadClip("clean-chords");
    const std::vector<float> second(clip.begin() + 24000, clip.begin() + 72000);
    Rig rig;

    if (pack.presets.empty())
    {
        return;
    }

    rig.Load(pack.presets.front());
    rig.Settle(1.0);
    double before = Measure(rig.Play(second)).largestStep;
    int clicks = 0;

    // Through the whole pack in order, and back to the first: each change made mid-note.
    for (std::size_t i = 1; i <= pack.presets.size(); ++i)
    {
        const auto& next = pack.presets[i % pack.presets.size()];
        rig.Load(next);
        const double during = Measure(rig.Play(second)).largestStep;
        const double after = Measure(rig.Play(second)).largestStep;
        // A click is a jump no bigger sample-to-sample movement in either preset explains.
        const bool clicked = during > 2.0 * std::max(before, after) + 0.05;
        clicks += clicked ? 1 : 0;
        Check(!clicked, "into " + next.name + " without a click",
              "step " + Num(during, 3) + " against " + Num(std::max(before, after), 3));
        before = after;
    }

    std::cout << "  " << pack.presets.size() << " changes, " << clicks << " clicked" << std::endl;
}
} // namespace

int main(int argc, char** argv)
{
    std::cout << "=== SepiaFactoryPackTests ===" << std::endl;
    guitarfx::RegisterAllEffects();

    const std::string mode = argc > 1 ? argv[1] : "";
    const bool measureOnly = mode == "--measure" && argc > 2;
    const auto pack = LoadPack();

    if (pack)
    {
        TestSelfContained(*pack);
        TestOfferedById(*pack);
        const json measured = TestLevels(*pack, measureOnly);

        if (measureOnly)
        {
            std::ofstream out(argv[2], std::ios::binary);
            out << json{{"targetLufs", kTargetLufs}, {"presets", measured}}.dump(1) << std::endl;
        }
        else
        {
            TestSwitchingDoesNotClick(*pack);
        }
    }

    std::cout << "\n" << (gChecks - gFailures) << "/" << gChecks << " checks passed" << std::endl;
    return gFailures == 0 ? 0 : 1;
}
